    "import geopandas as gpd, numpy as np\nusw=gpd.read_file('dataset/USA_shallow_waters.shp'); gsw=gpd.read_file('dataset/Global_shallow_waters.shp')\nprint(usw.shape, usw.crs, usw.total_bounds, usw.columns.tolist())\nprint(gsw.shape, gsw.crs, gsw.total_bounds, gsw.columns.tolist())\nprint(om[['temp','salinity']].describe())",
    "import os, shapely\nfrom shapely.geometry import Point\nos.makedirs('pred_results',exist_ok=True)\nsgd=sg.dissolve().reset_index(drop=True)[['geometry']]\nsgd.to_file('pred_results/USA_seagrass_dissolved.shp')\ngeom=sgd.geometry.iloc[0]; print(geom.geom_type, geom.area/1e6,'km2')\nrng=np.random.default_rng(42)\nprep=shapely.prepared.prep(geom) if hasattr(shapely,'prepared') else None\nfrom shapely.prepared import prep as _prep; pg=_prep(geom)\nminx,miny,maxx,maxy=geom.bounds; pts=[]\nwhile len(pts)<5000:\n    xs=rng.uniform(minx,maxx,20000); ys=rng.uniform(miny,maxy,20000)\n    inside=shapely.contains_xy(geom,xs,ys)\n    pts+=list(zip(xs[inside],ys[inside]))\npts=pts[:5000]\nrp=gpd.GeoDataFrame({'CID':1,'presence':1},geometry=gpd.points_from_xy(*zip(*pts)),crs=sg.crs)\nrp.to_file('pred_results/seagrass_random_points.shp'); print(len(rp))",
