    "def expvg(h,n,s,r): return n+s*(1-np.exp(-3*h/r))\ndef emp_vg(xy,z,nb=12):\n    from scipy.spatial.distance import pdist\n    h=pdist(xy); g=0.5*pdist(z[:,None],'sqeuclidean')\n    hmax=h.max()/2; edges=np.linspace(0,hmax,nb+1)\n    idx=np.digitize(h,edges)-1; ok=(idx>=0)&(idx<nb)\n    cnt=np.bincount(idx[ok],minlength=nb); gs=np.bincount(idx[ok],g[ok],minlength=nb)\n    m=cnt>0; return (0.5*(edges[1:]+edges[:-1]))[m], gs[m]/cnt[m], cnt[m], hmax\ndef fit_vg(xy,z):\n    hc,gm,cnt,hmax=emp_vg(xy,z); v=max(z.var(),1e-6)\n    try:\n        p,_=curve_fit(expvg,hc,gm,p0=[0.1*v,v,hmax/2],bounds=([0,1e-8,res/2],[2*v,10*v,10*hmax]),sigma=1/np.sqrt(cnt),maxfev=2000)\n    except Exception: p=np.array([0.1*v,0.9*v,hmax/2])\n    return p\ndef cov_mat(h,p): n,s,r=p; C=s*np.exp(-3*h/r); return np.where(h==0,C+n,C)\nfrom scipy.spatial.distance import cdist\ncenters=km.cluster_centers_; ctree=cKDTree(centers)\nNS=30; KSUB=100\ndef ebk_spectra(z,seed=0):\n    rg=np.random.default_rng(seed); spec=[]\n    for c in centers:\n        _,ii=tree.query(c,k=KSUB); xy=P[ii]; zz=z[ii]\n        p0=fit_vg(xy,zz); ps=[p0]\n        C=cov_mat(cdist(xy,xy),p0)+1e-9*np.eye(KSUB); L=np.linalg.cholesky(C)\n        for s in range(NS):\n            sim=zz.mean()+L@rg.standard_normal(KSUB)\n            ps.append(fit_vg(xy,sim))\n        spec.append(np.array(ps))\n    return spec\nimport time; t=time.time()\nspec_T=ebk_spectra(om.temp.values.astype(float)); print(time.time()-t)\nprint(spec_T[0][:3], np.median([s[0] for s in spec_T],axis=0))",
    'from rasterio import features\nfrom rasterio.transform import from_origin\ntransform=from_origin(gxmin,gymax,res,res)\nshal=features.rasterize([(g,1) for g in list(gsw.geometry)+list(usw.geometry)],out_shape=(nrow,ncol),transform=transform,all_touched=True,fill=0).astype(bool).ravel()\nprint(shal.sum(), (shal&~pmask).sum())\npredmask=pmask|shal\ngidx=np.where(predmask)[0]; G=np.c_[GX.ravel()[gidx],GY.ravel()[gidx]]\n_,gsub=ctree.query(G); _,gnb=tree.query(G,k=24)\nprint(len(gidx))',
    'def ebk_predict(z,spec):\n    pred=np.full(len(G),np.nan); se=np.full(len(G),np.nan); K=gnb.shape[1]\n    for s in range(len(centers)):\n        sel=np.where(gsub==s)[0]\n        if len(sel)==0: continue\n        nb=gnb[sel]; xy=P[nb]                       # (m,K,2)\n        Dnn=np.linalg.norm(xy[:,:,None,:]-xy[:,None,:,:],axis=-1)\n        D0=np.linalg.norm(xy-G[sel][:,None,:],axis=-1)\n        zn=z[nb]; preds=[]; vars_=[]\n        for p in spec[s]:\n            A=np.ones((len(sel),K+1,K+1)); A[:,K,K]=0\n            A[:,:K,:K]=cov_mat(Dnn,p)+1e-9*np.eye(K)\n            b=np.ones((len(sel),K+1)); b[:,:K]=p[0]*(D0==0)+p[1]*np.exp(-3*D0/p[2])\n            w=np.linalg.solve(A,b[...,None])[...,0]\n            preds.append((w[:,:K]*zn).sum(1))\n            vars_.append(p[0]+p[1]-(w*b).sum(1))\n        preds=np.array(preds); vars_=np.array(vars_)\n        pred[sel]=preds.mean(0)\n        se[sel]=np.sqrt(np.maximum(vars_.mean(0)+preds.var(0),0))  # mixture variance\n    return pred,se\nt=time.time(); zT=om.temp.values.astype(float)\npredT,seT=ebk_predict(zT,spec_T); print(time.time()-t, np.nanmin(predT),np.nanmax(predT), np.isnan(predT).sum())',
    "import rasterio\nzS=om.salinity.values.astype(float)\nspec_S=ebk_spectra(zS,seed=1); predS,seS=ebk_predict(zS,spec_S)\nprint(np.nanmin(predS),np.nanmax(predS))\ndef write(arr_vals,path):\n    a=np.full(nrow*ncol,-9999.,dtype='float32'); a[gidx]=arr_vals; a=a.reshape(nrow,ncol)\n    with rasterio.open(path,'w',driver='GTiff',height=nrow,width=ncol,count=1,dtype='float32',crs=om.crs,transform=transform,nodata=-9999.) as dst: dst.write(a,1)\n    return np.where(a==-9999,np.nan,a)\ntempR=write(predT,'pred_results/EBK_temp.tif'); salR=write(predS,'pred_results/EBK_salinity.tif')\nwrite(seT,'pred_results/EBK_temp_stderr.tif'); write(seS,'pred_results/EBK_salinity_stderr.tif')\n# quick hold-out check: kriged value at data point vs observed via nearest-cell lookup\nr,c=rasterio.transform.rowcol(transform,X,Y)\nprint('temp cell-vs-obs MAE', np.nanmean(np.abs(tempR[r,c]-zT)),'sal MAE',np.nanmean(np.abs(salR[r,c]-zS)))",
    "usmask=features.rasterize([(g,1) for g in usw.geometry],out_shape=(nrow,ncol),transform=transform,all_touched=False,fill=0).astype(bool)\nprint('study cells',usmask.sum())\ninside=rp.within(usw.union_all()); print('presence in study area',inside.sum())\npr,pc=rasterio.transform.rowcol(transform,rp.geometry.x.values,rp.geometry.y.values)\npT=tempR[pr,pc]; pS=salR[pr,pc]; okp=~np.isnan(pT)&~np.isnan(pS)\nprint('presence with values',okp.sum())\nbr,bc=np.where(usmask&~np.isnan(tempR)&~np.isnan(salR))\n# exclude cells containing presence (cell-based background as in MaxEnt)\npres_cells=set(zip(pr[okp],pc[okp]))\nprint('bg cells',len(br), 'of which presence cells', sum((a,b) in pres_cells for a,b in zip(br,bc)))",
    "from sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import roc_auc_score\nfrom sklearn.model_selection import StratifiedKFold\nins=inside.values\nXp=np.c_[pT[ins],pS[ins]].astype(float); Xb=np.c_[tempR[br,bc],salR[br,bc]].astype(float)\nlo=Xb.min(0); hi=Xb.max(0)\nnk=15; knots=[np.linspace(0,1,nk+2)[1:-1]]*2\ndef feats(Xr):\n    U=(Xr-lo)/(hi-lo); cols=[U[:,0],U[:,1],U[:,0]**2,U[:,1]**2,U[:,0]*U[:,1]]\n    for j in range(2):\n        for k in knots[j]:\n            cols.append(np.maximum(0,U[:,j]-k)/(1-k)); cols.append(np.maximum(0,k-U[:,j])/k)\n    return np.column_stack(cols)\nXall=np.vstack([Xp,Xb]); yall=np.r_[np.ones(len(Xp)),np.zeros(len(Xb))]\nwall=np.r_[np.ones(len(Xp)),np.full(len(Xb),100.)]\nFall=feats(Xall)\nskf=StratifiedKFold(5,shuffle=True,random_state=0)\nfor C in [0.01,0.05,0.1,0.5,1,5]:\n    aucs=[]\n    for tr,te in skf.split(Fall,yall):\n        m=LogisticRegression(penalty='l1',C=C,solver='liblinear',max_iter=5000).fit(Fall[tr],yall[tr],sample_weight=wall[tr])\n        aucs.append(roc_auc_score(yall[te],m.decision_function(Fall[te])))\n    print(C,np.mean(aucs).round(4))",
    "import warnings; warnings.filterwarnings('ignore')\nmdl=LogisticRegression(penalty='l1',C=0.5,solver='liblinear',max_iter=10000).fit(Fall,yall,sample_weight=wall)\ncoef=mdl.coef_[0]; print('nonzero coefs',(coef!=0).sum(),'of',len(coef))\ndef eta(Xr):\n    Xc=np.clip(Xr,lo,hi)  # clamping to training range\n    return feats(Xc)@coef\neb=eta(Xb); shift=np.log(np.exp(eb-eb.max()).sum())+eb.max()\nrawb=np.exp(eb-shift); H=-(rawb*np.log(rawb)).sum()\ndef cloglog(Xr): return 1-np.exp(-np.exp(eta(Xr)-shift+H))\npp=cloglog(Xp); pb=cloglog(Xb)\nprint('AUC train',roc_auc_score(yall,np.r_[pp,pb]), 'entropy',H)\n# threshold: maximise sensitivity+specificity (also report default 0.5)\nths=np.linspace(0.01,0.99,99); tss=[(pp>=t).mean()+(pb<t).mean()-1 for t in ths]\nthr=ths[int(np.argmax(tss))]; print('thr',thr,'TSS',max(tss), 'pres>=0.5',(pp>=0.5).mean(),'bg>=0.5',(pb>=0.5).mean())",
    "cut=0.5\nbx,by=rasterio.transform.xy(transform,br,bc)\ntf=gpd.GeoDataFrame({\n 'PRESENCE':np.r_[np.ones(len(Xp),int),np.zeros(len(Xb),int)],\n 'EBK_TEMP':Xall[:,0],'EBK_SAL':Xall[:,1],\n 'TRAINED':np.ones(len(Xall),int)},\n geometry=gpd.points_from_xy(np.r_[rp.geometry.x.values[ins],bx],np.r_[rp.geometry.y.values[ins],by]),crs=om.crs)\ntf['PROB_PRES']=np.r_[pp,pb]; tf['PRED_CLASS']=(tf.PROB_PRES>=cut).astype(int)\ntf['FIT_CLASS']=np.select([(tf.PRESENCE==1)&(tf.PRED_CLASS==1),(tf.PRESENCE==1)&(tf.PRED_CLASS==0),(tf.PRESENCE==0)&(tf.PRED_CLASS==1)],\n                          ['Presence-correct','Presence-omission','Background-potential presence'],'Background-absence')\ntf.to_file('pred_results/seagrass_trained_features.shp'); print(tf.FIT_CLASS.value_counts())\ndef pred_raster(mask,path):\n    valid=mask&~np.isnan(tempR)&~np.isnan(salR)\n    out=np.full((nrow,ncol),-9999.,'float32')\n    out[valid]=cloglog(np.c_[tempR[valid],salR[valid]].astype(float))\n    with rasterio.open(path,'w',driver='GTiff',height=nrow,width=ncol,count=1,dtype='float32',crs=om.crs,transform=transform,nodata=-9999.) as dst: dst.write(out,1)\n    return np.where(out==-9999,np.nan,out)\ngmask=features.rasterize([(g,1) for g in gsw.geometry],out_shape=(nrow,ncol),transform=transform,fill=0).astype(bool)\nglob=pred_raster(gmask,'pred_results/seagrass_predict_global.tif')\nusa=pred_raster(usmask,'pred_results/seagrass_predict_USA_training.tif')\nprint(np.nanmean(glob), (glob>=cut).sum(), (~np.isnan(glob)).sum(), np.nanmean(usa))",
    "import matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt\next=[gxmin,gxmin+ncol*res,gymax-nrow*res,gymax]\nfig,ax=plt.subplots(2,2,figsize=(16,9))\nfor a,arr,t,cm in [(ax[0,0],tempR,'EBK temperature (°C)','coolwarm'),(ax[0,1],salR,'EBK salinity','viridis'),(ax[1,0],glob,'Seagrass presence probability (global shallow waters)','YlGn')]:\n    im=a.imshow(arr,extent=ext,cmap=cm); a.set_title(t); plt.colorbar(im,ax=a,shrink=.7)\na=ax[1,1]; usw.boundary.plot(ax=a,color='grey',lw=.5)\nim=a.imshow(usa,extent=ext,cmap='YlGn',vmin=0,vmax=1); a.set_xlim(-1.08e7,-5.2e6); a.set_ylim(3e6,6e6)\ntf[tf.PRESENCE==1].plot(ax=a,markersize=1,color='red'); a.set_title('USA training: probability + presence points'); plt.colorbar(im,ax=a,shrink=.7)\nplt.tight_layout(); plt.savefig('pred_results/seagrass_maxent_maps.png',dpi=110); plt.close()\nprint(sorted(os.listdir('pred_results')))",
